\begin{aligned}
\mathrm{IsTerminal}_{\mathcal C}(T)&\leftrightarrow T\in\mathrm{Ob}(\mathcal C)\land\forall X\in\mathrm{Ob}(\mathcal C)\ \exists!u\in\mathrm{Hom}_{\mathcal C}(X,T)\ (u=u),\\
\mathrm{IsInitial}_{\mathcal C}(T)&\leftrightarrow T\in\mathrm{Ob}(\mathcal C)\land\forall X\in\mathrm{Ob}(\mathcal C)\ \exists!u\in\mathrm{Hom}_{\mathcal C}(T,X)\ (u=u),\\
\mathrm{IsProduct}_{\mathcal C}(P,p,q,A,B)&\leftrightarrow A,B,P\in\mathrm{Ob}(\mathcal C)\land p\in\mathrm{Hom}_{\mathcal C}(P,A)\land q\in\mathrm{Hom}_{\mathcal C}(P,B)\\
&\land\forall X\in\mathrm{Ob}(\mathcal C)\ \forall f\in\mathrm{Hom}_{\mathcal C}(X,A)\ \forall g\in\mathrm{Hom}_{\mathcal C}(X,B)\ \exists!u\in\mathrm{Hom}_{\mathcal C}(X,P)\ (p\circ u=f\land q\circ u=g).
\end{aligned}
